// Baird 反例：7 个状态、8 维特征。讲座字幕把特征索引念得完全读不出来，
// 这里按她口述的两个数（w 全 1 时 V̂(s₁)=3、V̂(s₇)=3）反推重建：
//   x(sᵢ) = 2eᵢ + e₈  (i=1..6)      x(s₇) = e₇ + 2e₈
// 所有奖励为 0，所以真值 V ≡ 0。本片的发散数字由独立脚本核算。
function bxf(s){var x=[0,0,0,0,0,0,0,0];
  if(s<=6){x[s-1]=2;x[7]=1;}else{x[6]=1;x[7]=2;}return x;}
function bV(w,s){var x=bxf(s),t=0,i;for(i=0;i<8;i++)t+=x[i]*w[i];return t;}

